"use strict";(globalThis.webpackChunkdocusaurus_resource=globalThis.webpackChunkdocusaurus_resource||[]).push([[2398],{16699:e=>{e.exports=JSON.parse('{"tag":{"label":"wcag","permalink":"/accessibility-hub/docs/tags/wcag","allTagsPath":"/accessibility-hub/docs/tags","count":13,"items":[{"id":"hot-topics/accessibility-audit","title":"Accessibility Audit","description":"Accessibility Audit covers the process and tools for evaluating digital content for accessibility compliance. This page will be expanded and curated with more detailed guidance and resources in the future.","permalink":"/accessibility-hub/docs/hot-topics/accessibility-audit"},{"id":"resources/learning-paths/index","title":"Accessibility Learning Paths","description":"Welcome to your guide for starting and advancing your accessibility journey. Whether you\'re looking for a quick-start plan, formal courses, certifications, or community connections, these resources will help you build and validate your skills.","permalink":"/accessibility-hub/docs/resources/learning-paths/"},{"id":"hot-topics/accessibility-testing","title":"Accessibility Testing","description":"Accessibility Testing covers the tools, methods, and best practices for evaluating digital content for accessibility. This page will be expanded and curated with more detailed guidance and resources in the future.","permalink":"/accessibility-hub/docs/hot-topics/accessibility-testing"},{"id":"for-developers/accessible-api-design-guide","title":"Accessible API Design for Developers","description":"Accessibility in software is often associated with user interfaces, but it is equally important in API and schema design. Accessible APIs improve usability for developers using assistive technologies, enhance code readability, and support better tooling integration. This guide outlines key strategies Java developers can adopt to make their APIs more inclusive.","permalink":"/accessibility-hub/docs/for-developers/accessible-api-design-guide"},{"id":"for-developers/accessible-web-dev-checklist","title":"Accessible Web Development Checklist","description":"A comprehensive checklist based on WCAG 2.1 Level AA and best practices from W3C, WebAIM, and Section508.gov.","permalink":"/accessibility-hub/docs/for-developers/accessible-web-dev-checklist"},{"id":"hot-topics/aria-roles","title":"ARIA Roles","description":"ARIA Roles define the purpose of elements in web content for assistive technologies. More curated content and examples will be added to this page in the future.","permalink":"/accessibility-hub/docs/hot-topics/aria-roles"},{"id":"hot-topics/color-contrast","title":"Color Contrast","description":"Color Contrast is essential for readability and accessibility, especially for users with visual impairments. This page will be expanded and curated with more information and best practices in the future.","permalink":"/accessibility-hub/docs/hot-topics/color-contrast"},{"id":"community-contributions/contributing","title":"Contributing to the Accessibility Hub","description":"Thank you for your interest in contributing to our Accessibility Hub!","permalink":"/accessibility-hub/docs/community-contributions/contributing"},{"id":"resources/learning-paths/courses-programs","title":"Courses & Programs","description":"A mix of free and paid courses from trusted organizations.","permalink":"/accessibility-hub/docs/resources/learning-paths/courses-programs"},{"id":"resources/free-oss-resources","title":"Guides, Open source Tools and Patterns","description":"A curated list of high-quality, no-cost guides, tools, and patterns.","permalink":"/accessibility-hub/docs/resources/free-oss-resources"},{"id":"for-developers/how-to-contribute","title":"How to contribute","description":"Developers play a crucial role in making the world more accessible by designing and building digital experiences that are inclusive of people with disabilities. Here are several impactful ways developers can contribute:","permalink":"/accessibility-hub/docs/for-developers/how-to-contribute"},{"id":"resources/legal-standards","title":"Legal standards","description":"Legal & Standards Overview","permalink":"/accessibility-hub/docs/resources/legal-standards"},{"id":"resources/learning-paths/quickstart-guide","title":"Quickstart Guide with FOSS","description":"This plan is designed to get you hands-on with core accessibility concepts in one week, using freely available, and wherever possible, open-source tools.","permalink":"/accessibility-hub/docs/resources/learning-paths/quickstart-guide"}],"unlisted":false}}')}}]);